import { useState, useEffect, useCallback } from "react";
import { affectationApi } from "../api/api";
import StatsBar from "./StatsBar";

const STATUS = {
  EN_ATTENTE: { label: "En attente",  bg: "rgba(245,158,11,0.12)",  color: "#f59e0b", dot: "#f59e0b" },
  VALIDEE:    { label: "Validée",     bg: "rgba(16,185,129,0.12)",  color: "#10b981", dot: "#10b981" },
  REFUSEE:    { label: "Refusée",     bg: "rgba(239,68,68,0.12)",   color: "#ef4444", dot: "#ef4444" },
};
// Shared badge configs — import this in each component
export const STATUS_AFFECTATION = {
  EN_ATTENTE: {
    label: "En attente",
    bg: "#fef3c7", color: "#92400e",
    border: "#f59e0b", dot: "#f59e0b",
  },
  VALIDEE: {
    label: "Validée",
    bg: "#d1fae5", color: "#065f46",
    border: "#10b981", dot: "#10b981",
  },
  REFUSEE: {
    label: "Refusée",
    bg: "#fee2e2", color: "#991b1b",
    border: "#ef4444", dot: "#ef4444",
  },
};

export const STATUS_SOUTENANCE = {
  PLANIFIEE: {
    label: "Planifiée",
    bg: "#dbeafe", color: "#1e40af",
    border: "#3b82f6", dot: "#3b82f6",
  },
  TERMINEE: {
    label: "Terminée",
    bg: "#d1fae5", color: "#065f46",
    border: "#10b981", dot: "#10b981",
  },
  ANNULEE: {
    label: "Annulée",
    bg: "#fee2e2", color: "#991b1b",
    border: "#ef4444", dot: "#ef4444",
  },
  EN_COURS: {
    label: "En cours",
    bg: "#fef3c7", color: "#92400e",
    border: "#f59e0b", dot: "#f59e0b",
  },
};

export const STATUS_CRENEAU = {
  DISPONIBLE: {
    label: "Disponible",
    bg: "#d1fae5", color: "#065f46",
    border: "#10b981",
  },
  OCCUPE: {
    label: "Occupé",
    bg: "#fef3c7", color: "#92400e",
    border: "#f59e0b",
  },
};

export function Badge({ config }) {
  if (!config) return null;
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 6,
      background: config.bg,
      color: config.color,
      border: `1px solid ${config.border}`,
      padding: "4px 12px", borderRadius: 20,
      fontSize: 12, fontWeight: 600,
    }}>
      {config.dot && (
        <span style={{
          width: 6, height: 6, borderRadius: "50%",
          background: config.dot, flexShrink: 0,
        }} />
      )}
      {config.label}
    </span>
  );
}
function StatusBadge({ statut }) {
  const s = STATUS[statut] || STATUS.EN_ATTENTE;
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 6,
      background: s.bg, color: s.color,
      padding: "4px 10px", borderRadius: 20, fontSize: 12, fontWeight: 500,
    }}>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: s.dot, display: "inline-block" }} />
      {s.label}
    </span>
  );
}

function StatCard({ label, value, color }) {
  return (
    <div style={{
      background: "var(--surface)", border: "1px solid var(--border)",
      borderRadius: "var(--radius)", padding: "20px 24px",
    }}>
      <div style={{ fontSize: 28, fontWeight: 600, color: color || "var(--text)", letterSpacing: "-0.5px" }}>
        {value}
      </div>
      <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 4, textTransform: "uppercase", letterSpacing: "0.06em" }}>
        {label}
      </div>
    </div>
  );
}

export default function ValidationAffectations() {
  const [affectations, setAffectations] = useState([]);
  const [loading, setLoading]           = useState(true);
  const [error, setError]               = useState(null);
  const [filter, setFilter]             = useState("EN_ATTENTE");
  const [commentaires, setCommentaires] = useState({});
  const [openRefus, setOpenRefus]       = useState(null);
  const [actionLoading, setActionLoading] = useState(null);

  const load = useCallback(async () => {
    try {
      setLoading(true);
      const data = await affectationApi.getAll();
      setAffectations(data);
      setError(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleValider = async (id) => {
    setActionLoading(id + "-valider");
    try {
      await affectationApi.valider(id);
      await load();
    } catch (e) { setError(e.message); }
    finally { setActionLoading(null); }
  };

  const handleRefuser = async (id) => {
    const c = commentaires[id]?.trim();
    if (!c) { setError("Un commentaire est requis pour refuser."); return; }
    setActionLoading(id + "-refuser");
    try {
      await affectationApi.refuser(id, c);
      setOpenRefus(null);
      await load();
    } catch (e) { setError(e.message); }
    finally { setActionLoading(null); }
  };

  const handleValiderToutes = async () => {
    setActionLoading("all");
    try {
      await affectationApi.validerToutes();
      await load();
    } catch (e) { setError(e.message); }
    finally { setActionLoading(null); }
  };

  const filters = ["EN_ATTENTE", "VALIDEE", "REFUSEE", "TOUT"];
  const filtered = filter === "TOUT"
    ? affectations
    : affectations.filter(a => a.statut === filter);

  const count = (s) => affectations.filter(a => a.statut === s).length;

  if (loading) return <LoadingState />;

  return (
    <div style={{ animation: "fadeIn 0.3s ease" }}>
      <style>{`
        @keyframes fadeIn { from { opacity:0; transform:translateY(8px) } to { opacity:1; transform:translateY(0) } }
        .aff-card { transition: border-color 0.15s; }
        .aff-card:hover { border-color: var(--border2) !important; }
        .btn-action { transition: opacity 0.15s, transform 0.1s; }
        .btn-action:hover { opacity: 0.85; }
        .btn-action:active { transform: scale(0.97); }
        .filter-pill { transition: all 0.15s; }
        .filter-pill:hover { border-color: var(--border2) !important; }
      `}</style>

      {/* En-tête */}
      <div style={{ marginBottom: 28 }}>
        <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.08em", marginBottom: 6 }}>
          Phase 1
        </div>
        <h1 style={{ fontSize: 24, fontWeight: 600, color: "var(--text)", letterSpacing: "-0.4px" }}>
          Validation des affectations
        </h1>
      </div>

      {/* Stats */}
      <StatsBar stats={[
        { label: "En attente", value: count("EN_ATTENTE"), total: affectations.length, color: "var(--amber)" },
        { label: "Validées",   value: count("VALIDEE"),    total: affectations.length, color: "var(--green)" },
        { label: "Refusées",   value: count("REFUSEE"),    total: affectations.length, color: "var(--red)"   },
        { label: "Total",      value: affectations.length, color: "var(--text)"                              },
      ]} />

      {/* Barre de filtres */}
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 20, flexWrap: "wrap" }}>
        {filters.map(f => (
          <button key={f} className="filter-pill"
            onClick={() => setFilter(f)}
            style={{
              padding: "6px 14px", borderRadius: 20, fontSize: 13,
              border: `1px solid ${filter === f ? "var(--accent)" : "var(--border)"}`,
              background: filter === f ? "rgba(59,130,246,0.1)" : "transparent",
              color: filter === f ? "var(--accent)" : "var(--muted2)",
              fontWeight: filter === f ? 500 : 400,
            }}>
            {f === "TOUT" ? "Toutes" : STATUS[f]?.label}
            {f !== "TOUT" && (
              <span style={{ marginLeft: 6, fontSize: 11, opacity: 0.7 }}>
                {count(f)}
              </span>
            )}
          </button>
        ))}

        {count("EN_ATTENTE") > 0 && (
          <button className="btn-action"
            onClick={handleValiderToutes}
            disabled={actionLoading === "all"}
            style={{
              marginLeft: "auto", padding: "6px 16px", borderRadius: 8,
              border: "none", background: "var(--accent)", color: "#fff",
              fontSize: 13, fontWeight: 500,
              opacity: actionLoading === "all" ? 0.6 : 1,
            }}>
            {actionLoading === "all" ? "En cours..." : `Valider toutes (${count("EN_ATTENTE")})`}
          </button>
        )}
      </div>

      {error && (
        <div style={{
          background: "rgba(239,68,68,0.1)", border: "1px solid rgba(239,68,68,0.3)",
          color: "#ef4444", borderRadius: "var(--radius)", padding: "10px 14px",
          fontSize: 13, marginBottom: 16,
        }}>
          {error}
        </div>
      )}

      {filtered.length === 0 && (
        <div style={{ textAlign: "center", padding: "60px 0", color: "var(--muted)" }}>
          Aucune affectation dans cette catégorie.
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {filtered.map(a => (
          <div key={a.id} className="aff-card"
            style={{
              background: "var(--surface)", border: "1px solid var(--border)",
              borderRadius: "var(--radius-lg)", padding: "20px 24px",
            }}>
            {/* Header carte */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
              <div>
                <div style={{ fontSize: 15, fontWeight: 500, color: "var(--text)", marginBottom: 3 }}>
                  {a.binome?.etudiant1?.nom} & {a.binome?.etudiant2?.nom}
                </div>
                <div style={{ fontSize: 12, color: "var(--muted)", fontFamily: "'DM Mono', monospace" }}>
                  Moy. {a.binome?.moyenneBinome?.toFixed(2)} / 20 — Score {a.score?.toFixed(1)} pts
                </div>
              </div>
              <StatusBadge statut={a.statut} />
            </div>

            {/* Infos */}
            <div style={{
              display: "grid", gridTemplateColumns: "1fr 1fr",
              gap: "8px 32px", borderTop: "1px solid var(--border)", paddingTop: 14, marginBottom: 16,
            }}>
              {[
                ["Sujet",      a.sujet?.titre],
                ["Encadrant",  a.sujet?.encadrant?.nom],
                ["Département",a.sujet?.encadrant?.departement],
                ["Difficulté", a.sujet?.difficulte ? `Niveau ${a.sujet.difficulte}` : "—"],
              ].map(([label, val]) => (
                <div key={label}>
                  <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 2 }}>
                    {label}
                  </div>
                  <div style={{ fontSize: 13, color: "var(--text)", fontWeight: 400 }}>
                    {val || "—"}
                  </div>
                </div>
              ))}
            </div>

            {/* Commentaire admin si présent */}
            {a.commentaireAdmin && (
              <div style={{
                background: "var(--surface2)", borderRadius: 8,
                padding: "8px 12px", fontSize: 12, color: "var(--muted2)",
                marginBottom: 12, borderLeft: "3px solid var(--border2)",
              }}>
                {a.commentaireAdmin}
              </div>
            )}

            {/* Actions */}
            {!a.verrouillee ? (
              <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
                <button className="btn-action"
                  onClick={() => handleValider(a.id)}
                  disabled={actionLoading === a.id + "-valider"}
                  style={{
                    padding: "7px 16px", borderRadius: 8, border: "1px solid var(--green)",
                    background: "rgba(16,185,129,0.08)", color: "var(--green)",
                    fontSize: 13, fontWeight: 500,
                    opacity: actionLoading === a.id + "-valider" ? 0.6 : 1,
                  }}>
                  {actionLoading === a.id + "-valider" ? "..." : "Valider"}
                </button>

                <button className="btn-action"
                  onClick={() => setOpenRefus(openRefus === a.id ? null : a.id)}
                  style={{
                    padding: "7px 16px", borderRadius: 8, border: "1px solid var(--border2)",
                    background: "transparent", color: "var(--muted2)", fontSize: 13,
                  }}>
                  Refuser
                </button>

                {openRefus === a.id && (
                  <div style={{ display: "flex", gap: 8, width: "100%", marginTop: 4 }}>
                    <input
                      autoFocus
                      placeholder="Raison du refus..."
                      value={commentaires[a.id] || ""}
                      onChange={e => setCommentaires(p => ({ ...p, [a.id]: e.target.value }))}
                      style={{
                        flex: 1, padding: "7px 12px", borderRadius: 8,
                        border: "1px solid var(--border2)", background: "var(--surface2)",
                        color: "var(--text)", outline: "none",
                      }}
                    />
                    <button className="btn-action"
                      onClick={() => handleRefuser(a.id)}
                      disabled={actionLoading === a.id + "-refuser"}
                      style={{
                        padding: "7px 14px", borderRadius: 8, border: "none",
                        background: "var(--red)", color: "#fff", fontSize: 13, fontWeight: 500,
                      }}>
                      {actionLoading === a.id + "-refuser" ? "..." : "Confirmer"}
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div style={{ fontSize: 12, color: "var(--muted)", fontStyle: "italic" }}>
                Affectation verrouillée — aucune modification possible
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

function LoadingState() {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      {[1,2,3].map(i => (
        <div key={i} style={{
          background: "var(--surface)", border: "1px solid var(--border)",
          borderRadius: "var(--radius-lg)", padding: "20px 24px", height: 120,
          opacity: 1 - i * 0.15,
        }} />
      ))}
    </div>
  );
}
